="도움 보따리 (8%)",items={{id="Elixir_hp_02",count=2,name="명맥의 신약"}}},{maxRoll=79,grade="도움 보따리 (7%)",items={{id="Elixir_stamina_02",count=2,name="활력의 신약"}}},{maxRoll=86,grade="도움 보따리 (7%)",items={{id="Elixir_weight_02",count=2,name="거인의 신약"}}},{maxRoll=93,grade="도움 보따리 (7%)",items={{id="Elixir_workspeed_02",count=2,name="근로의 신약"}}},{maxRoll=100,grade="도움 보따리 (7%)",items={{id="Elixir_attack_02",count=2,name="맹격의 신약"}}}}}function selectDonationConsumable(a)local b=BundleCatalog[a]if type(b)~="table"then return nil,nil,"존재하지 않는 후원 번들입니다: "..tostring(a)end;local c=tonumber(b[#b].maxRoll)if c==nil or c<1 or c~=math.floor(c)then return nil,nil,"후원 번들의 확률 설정이 올바르지 않습니다."end;local d=math.random(1,c)for e,f in ipairs(b)do if d<=f.maxRoll then local g=f.items[math.random(1,#f.items)]return g,f.grade,nil end end;return nil,nil,"후원 아이템 룰렛 목록을 선택하지 못했습니다."end;function selectDonationSummonPal(a)local h,i,j=selectDonationConsumable(a)if h==nil then return nil,nil,nil,j end;if type(h.id)~="string"or h.id==""then return nil,nil,nil,"랜덤 팰 목록의 ID 설정이 올바르지 않습니다."end;return h.id,tostring(h.name or h.id),tostring(i or"일반"),nil end;function selectDonationItemCount(g)if type(g)~="table"then return nil,"보상 아이템 설정이 올바르지 않습니다."end;local k=tonumber(g.minCount or g.count)local l=tonumber(g.maxCount or g.count)if k==nil or l==nil or k<1 or l<k or k~=math.floor(k)or l~=math.floor(l)then return nil,"보상 아이템 수량 설정이 올바르지 않습니다."end;return math.random(k,l),nil end